  Item_10105_Name = {
    Text = "Chrysalis de la jeune fille Ⅰ"
  },
  Item_10105_StoryDesc = {
    Text = "Offrir une coquille pure"
  },
  Item_10106_Desc = {
    Text = "Approvisionnement généreux approuvé par le directeur par intérim Czort.\nUne boîte en bois contenant des matériaux précieux, fournissant de l'aide aux Gardiens du secret pour accomplir les entraînements.\nChoisissez un des matériaux suivants :\nChapitre Secret Blanc Pur*12\nAffiner l'esprit*12\nCopie de conscience*12\nModèle de Gnosis*12"
  },
  Item_10106_Name = {
    Text = "Ⅱe approvisionnement (abandonné)"
  },
  Item_10107_Desc = {
    Text = "La nature du pacte est un savoir interdit et difficile à appréhender. Après avoir redessiné avec un émoi, la puissance du pacte sera renforcée"
  },
  Item_10107_Name = {
    Text = "Transcription du pacte secret (abandonné)"
  },
  Item_10108_Desc = {
    Text = "Nom élégant de la monnaie du royaume. Partout accessible, toujours nécessaire"
