  Item_94440_Name = {Text = "Mouchette"},
  Item_94441_Desc = {
    Text = "C'est la gnose perdue de l'ancienne volonté. Mythisag éveille la gnose du réveilleur par un rite mystique, et le réveilleur ainsi inspiré augmentera définitivement sa capacité spirituelle. \nConverti lors de l'obtention répétée de Mochia, utilisé pour activer l'illuminer de Mochia."
  },
  Item_94441_Name = {
    Text = "Fragment · Matsuka"
  },
  Item_94441_StoryDesc = {
    Text = "Obtenir répétitivement Moxia permet de convertir pour activer l'illumination de Moxia."
  },
  Item_94442_Desc = {
