  Item_9538_Name = {
    Text = "Fragment · Faros"
  },
  Item_9538_StoryDesc = {
    Text = "Obtenir répétitivement Faros permet de convertir pour activer l'illumination de Faros"
  },
  Item_9539_Desc = {
    Text = "Une permission spéciale fabriquée à partir de la technologie mystérieuse de Miss Winkle, apportée de sa planète d'origine. Elle peut comprimer le temps, accélérer son écoulement et aider le Gardien à accomplir rapidement l'épreuve. \n Dans les niveaux de « Ruines de la Fusion » et « Interdit Recueil », il est possible de consommer cet objet pour reproduire après avoir atteint trois étoiles."
  },
  Item_9539_Name = {
