  Item_9797_Name = {
    Text = "Jumeaux Distordus·noirⅥ"
  },
  Item_9797_StoryDesc = {
    Text = "Rituel sanglant"
  },
  Item_97989_Desc = {
    Text = "Obtenu après avoir acheté « Sujet principal » dans le « Registre des sujets ».\n« Debout au sommet du monde, profiter seul de la solitude du pouvoir. Ah, la vie d'un être immortel est vraiment monotone et ennuyeuse. »"
  },
  Item_97989_Name = {
    Text = "Hier impérissable : Lotan"
  },
  Item_97989_StoryDesc = {
